/// @file ndarray_all.h
/// @brief Convenience header that includes all NDArray functionality.
///
/// This header includes:
/// - Core NDArray and NDArrayView types with expression templates
/// - Binary operators (+, -, *)
/// - Element-wise functions (Max, Min)
///
/// Use this header for convenience when you need all NDArray features.
/// For minimal dependencies, include only the specific headers you need.

#ifndef AIFO_AIFOCORE_INCLUDE_AIFOCORE_MATH_NDARRAY_ALL_H_
#define AIFO_AIFOCORE_INCLUDE_AIFOCORE_MATH_NDARRAY_ALL_H_

#include "aifocore/math/ndarray.h"
#include "aifocore/math/ndarray_functions.h"
#include "aifocore/math/ndarray_operators.h"

#endif  // AIFO_AIFOCORE_INCLUDE_AIFOCORE_MATH_NDARRAY_ALL_H_
